import { DevMessageType } from "@/types/dev";
import { Message } from "@arco-design/web-react";
import { action, makeObservable, observable } from 'mobx';
import { CustomPageStore } from '@/components/CustomPage';
import { moduleStore } from 'react-converter-code';
import pageStore from "@/store/page";
import file from "@/store/file";
import app from "@/store/app";
import language from '@/store/language'
import { moduleSource } from "@/types/module";
import mainConfig from 'mainConfig';
import { loadScript } from "@/utils/lazyload";
import { dynamicCreateModule } from "@/environments/hoc";
import "@/layout/init";
import userStore from "@/store/userStore";
import plugins from "@/store/plugins";
import { IfrmaeWindowProps } from "@/types/iframe";

const win: IfrmaeWindowProps = window as any;

class Store {

    constructor(){
        makeObservable(this);
    }

    @observable notEditor = false;  // 无编辑器
    @action setNotEditor = (bool) => this.notEditor = bool;
    @observable isEditor = false;   // 是否存在编辑器
    @action setIsEditor = (bool) => this.isEditor = bool;


    @observable ready = false;
    @action setReady = (bool) => {
        this.ready = bool;
    }

    channelKey = "dev-editor-preview";  // 频道名称
    myChannel: BroadcastChannel; // 频道

    // 发送消息
    postMessage = (key: DevMessageType, data: any = {}) => {
        this.myChannel.postMessage({
            key,
            data,
        })
    }


    /**
     * 刷新预览页
     */
    resetView = (o: CustomPageStore) => {
        pageStore.current = o.uid;
        if(win.dev) win.dev.updateKey();    // 刷新预览页面
    }


    // 监听信息
    onHandleMessage = (event) => {
        if(typeof event.data == "object"){
            const { key, data } = event.data;
            switch(key){
                case DevMessageType.预览页面监测:
                    this.postMessage(DevMessageType.预览页面回应);
                    this.postMessage(DevMessageType.环境监测);  // 请求资源传递
                break;
                case DevMessageType.环境监测回应:
                    // 编辑器监测成果
                    this.setIsEditor(true);
                    Message.loading({
                        id: 'need_update',
                        content: '正在加载资源。。。',
                        duration: 9999999,
                    });
                break;
                case DevMessageType.资源传递:
                    console.log('资源传递', data)
                    const { pages, modules } = data;
                    // 模块需要优先添加
                    for (const item of modules) {
                        moduleStore.addElement({
                            ...item,
                            key: item.moduleId,
                            content: item.content,
                            source: moduleSource.custom,
                            jsxRender: item.jsxRender,
                            // render: dynamicCreateModule(item.jsxRender),
                            extraInfo: {
                                cssStr: item.content.cssStr,
                            }
                        } as any)
                    }
                    for (const item of modules) {
                        const option = {
                            uid: item.moduleId,
                            name: item.title,
                            isComponent: true,
                        };
                        const page = new CustomPageStore(option);
                        page.setData(item.content);
                        pageStore.pages[page.uid] = page;
                    }
                    for (const item of pages) {
                        const option = {
                            uid: item.pageId,
                            name: item.title,
                        };
                        const page = new CustomPageStore(option);
                        page.setJsxRender(item.jsxRender);
                        page.setData(item.content);
                        pageStore.pages[page.uid] = page;
                    }

                    file.setStore(data.fileStore);
                    app.setStore(data.appStore);
                    language.setStore(data.languageStore);
                    pageStore.setMenus(data.menus)
                    userStore.setStore(data.userStore);
                    plugins.setStore(data.pluginsStore);

                    Message.clear();
                    this.setReady(true);
                break;
                case DevMessageType.模块更新:
                    const module = pageStore.pages[data.moduleId];
                    module.setData(data.content);
                    moduleStore.elements.set(module.uid, {
                        ...moduleStore.elements.get(module.uid),
                        jsxRender: data.jsxRender,
                        // render: dynamicCreateModule(data.jsxRender),
                        extraInfo: {
                            cssStr: data.content.cssStr,
                        }
                    })
                    this.resetView(module)
                break;
                case DevMessageType.页面更新:
                    const page = pageStore.pages[data.pageId];
                    page.setJsxRender(data.jsxRender);
                    page.setData(data.content);
                    this.resetView(page);
                break;
            }
        }
    };

    // 加载依赖
    insetall = () => {
        this.postMessage(DevMessageType.环境监测)
    }

    init = () => {
        // 创建一个名为 "my_channel" 的广播频道
        this.myChannel = new BroadcastChannel(this.channelKey);
        this.myChannel.addEventListener('message', this.onHandleMessage);
        loadScript(mainConfig.typescriptURL).then(() => {
            this.insetall();
        })

        setTimeout(() => {
            if(!this.isEditor){
                this.setNotEditor(true);
            }
        },800)
    }

    unInit = () => {
        this.myChannel.removeEventListener('message', this.onHandleMessage);
        this.myChannel.close();
    }
}


export default new Store;