import React, { useEffect, useState } from "react";
import Store from './store';
import message from "./message";
import DevelopSetting, { settingStore } from "@/pages/preview/components/DevelopSetting";
import { useObserver } from "mobx-react-lite";
import { Button, Result } from "@arco-design/web-react";
import { MobileKey } from "@/types/mobile";
import _ from "lodash";
import { IfrmaeAppProps } from "@/types/iframe";
import file from "@/store/file";
import app from "@/store/app";
import language from '@/store/language'
import { moduleStore } from "react-converter-code";
import pageStore from "@/store/page";
import userStore from "@/store/userStore";
import pluginsStore from '@/store/plugins';
import { HashRouter, useParams } from "react-router-dom";


export default () => {

    const params: any = useParams();

    const { id, path } = params;
    const [store] = useState(() => new settingStore())

    useEffect(() => {
        message.init();
        return () => {
            message.unInit();
        }
    },[])


    /**
     * 监听App 页面事件
     */
    useEffect(() => {
        const handleMessage = (event) => {
            if(typeof event.data == "object"){
                const { key } = event.data;
                switch(key){
                    case MobileKey.IframeAppReady:
                        // 更新状态
                        store.setIsFrameReady(true);
                    break;
                }
            }
        };
    
        window.addEventListener('message', handleMessage);
    
        return () => {
            window.removeEventListener('message', handleMessage);
        };
    }, []);

    return useObserver(() => {

        useEffect(() => {
            const iframe = store.iframeRef.current;
            console.log('iframe', iframe)
            if(iframe){
                Object.assign(
                    iframe.contentWindow,
                    {
                        iframeApp: true,
                        moduleStore,
                        userStore,
                        fileStore: file,
                        app,
                        language,
                        pageStore,
                        pluginsStore
                    } as IfrmaeAppProps
                )
            }
        },[message.ready && store.isReady])

        if(message.notEditor) {
            return (
                <Result
                    status='warning'
                    title='未监测到编辑器'
                    subTitle='请打开编辑器后刷新当前页面'
                    extra={[
                        <Button key='again' style={{ margin: '0 16px' }}
                            onClick={() => {
                                location.reload();
                            }}
                        >
                            立即刷新
                        </Button>
                    ]}
                ></Result>
            )
        }

        if(!message.ready) return null;

        return (
            <HashRouter basename={`/dev-preview/${id}`} >
                <div className="h-full w-full flex flex-col ">
                    {store.isFrameReady? (
                        <DevelopSetting store={store} key={store.key}/>
                    ): null}
                    {store.isReady? (
                        <iframe
                            ref={store.iframeRef}
                            src={`${location.origin}/#/${path || ''}`}
                            className="grow"
                        >
                        </iframe>
                    ): null}
                </div>
            </HashRouter>
        )
    })
}